129	fn convert_type(def: parser::TypeDefinition<'_>, resolvers: &mut ResolverMap) -> async_graphql::dynamic::Type {
130	    match def {
131	        parser::TypeDefinition::Scalar(def) => async_graphql::dynamic::Scalar::new(def.name()).into(),
132	        parser::TypeDefinition::Object(def) => convert_object(def, resolvers),
133	        parser::TypeDefinition::Interface(def) => convert_iface(def),
134	        parser::TypeDefinition::Union(def) => convert_union(def),
135	        parser::TypeDefinition::Enum(def) => convert_enum(def),
136	        parser::TypeDefinition::InputObject(def) => convert_input_object(def),
137	    }
