140	fn convert_object(def: parser::ObjectDefinition<'_>, resolvers: &mut ResolverMap) -> async_graphql::dynamic::Type {
141	    use async_graphql::dynamic::*;
142	
143	    let mut object = Object::new(def.name());
144	
145	    for name in def.implements_interfaces() {
146	        object = object.implement(name);
147	    }
148	
149	    for field_def in def.fields() {
150	        let type_ref = convert_type_ref(field_def.ty());
151	        let resolver = std::sync::Mutex::new(
152	            resolvers
153	                .remove(&(def.name().into(), field_def.name().into()))
154	                .unwrap_or_else(|| Box::new(default_field_resolver(field_def.name()))),
155	        );
156	
157	        let mut field = Field::new(field_def.name(), type_ref, move |context| {
158	            let mut resolver = resolver.lock().expect("mutex to be unpoisoned");
159	            FieldFuture::Value(resolver.resolve(context).map(|value| {
160	                let value = async_graphql::Value::deserialize(value).unwrap();
161	                transform_into_field_value(value)
162	            }))
163	        });
164	
165	        for argument in field_def.arguments() {
166	            field = field.argument(convert_input_value(argument));
167	        }
168	
169	        object = object.field(field);
170	    }
171	
172	    object.into()
173	}
