178	            if let Some(async_graphql::Value::String(ty)) = fields.swap_remove("__typename") {
179	                FieldValue::from(value).with_type(ty)
180	            } else {
181	                FieldValue::from(value)
182	            }
183	        }
184	        async_graphql::Value::List(values) => FieldValue::list(values.into_iter().map(transform_into_field_value)),
185	        value => FieldValue::from(value),
